<template>
    <br>
    <div class="container mb-3 bg-ligt">
        <p>As Albert Camus said:</p>
        <blockquote cite="Albert Camus" >"One must imagine Sisyphus happy"</blockquote>
        <br>
        <address><p>Submit your records sending message in <i>demons-lsi-submit</i> channel in our discord</p></address>
    </div>
    <br>
    <div class="container mb-3">
        <div class="row">
            <div class="col-6 col-md-3">
                <div class="mb-3" v-for="(level, index) in levels">
                    <button 
                    class="btn w-100 mb-2"
                    :class="index == activeLevel ? 'btn-primary' : 'btn-secondary'"
                    @click.prevent="setActiveLevel(index)"
                    >{{ (index>74 ? "Legacy" : (index+1).toString())+" - "+ levels[index].name }}</button>
                </div>
            </div>
            <div class="col-6">

                <h2>{{ activeLevel == -1 ? "Select a level" : (levels[activeLevel].name + " (" + levels[activeLevel].difficulty + ")" ) }}</h2>

                <iframe width="900" height="500"
                class="mb-3"
                :src="activeVideo">
                </iframe> 



                <table v-if="activeLevel !== -1" class="table table-hover">
                    <thead>
                        <tr>
                            <th>Victor</th>
                            <th>Word</th>
                            <th>Video</th>
                        </tr>
                    </thead>
                    <tbody>
                        <tr 
                            v-for="(completion, index) in levels[activeLevel].completions"
                            :key="index"
                            
                        >
                            <td>{{ completion.victor }}</td>
                            <td>{{ completion.word }}</td>
                            <td>
                                <a v-if="completion.video != 'javascript:void(0)'" :href="completion.video" target="_blank">Watch</a>
                                <p v-else>No video</p>
                            </td>
                        </tr>
                    </tbody>
                </table>
                <br>
           </div>
        </div>
        <div class="row">
            <div class="col-md-3">
                <p>Sources for the difficulties:</p>
            </div>
            <div class="col">
                <a target="_blank" href="https://docs.google.com/spreadsheets/d/1YxUE2kkvhT2E6AjnkvTf-o8iu_shSLbuFkEFcZOvieA/edit?gid=0#gid=0"><img src="data:image/jpeg;base64," alt="Nlw"></a>
                <a target="_blank" href="https://aredl.net/"><img src="data:image/jpeg;base64," alt="aredl"></a>
                <a target="_blank" href="https://tsl.pages.dev/#/"><img src="data:image/jpeg;base64," alt="TSL"></a>
            </div>
       </div>
    </div>
</template>
<script>
export default{
    created(){
        this.getLevels();
    },
    data(){
        return{
            activeLevel: -1,
            activeVideo: "",
            levels: [],
        }
    },
    methods:{
        async getLevels(){
            let res = await fetch("levels.json");
            let data = await res.json();

            this.levels = data;
        },
        setActiveLevel(index){
            this.activeLevel = index;

            this.activeVideo = this.levels[index].video;
        }
    }
}

</script>